from lxml import etree
from typing import Dict


def parse_retention_policy(xml_content: str) -> Dict[str, int]:
    """
    Parse a document retention policy from XML content.

    The XML must contain a root <retention-policy> element with one or more
    <rule> children. Each <rule> has a required 'document-type' attribute
    (string) and a required <retention-years> child element (positive integer).
    Duplicate document-type entries are resolved by keeping the last occurrence.

    Args:
        xml_content: XML string provided by the user defining retention rules.
            This input comes from an untrusted source (user upload).

    Returns:
        Dictionary mapping document-type strings to retention-years integers.
        Returns an empty dictionary if the XML is malformed, missing required
        elements, contains invalid retention values, has an unexpected
        root element, or contains a DOCTYPE declaration.
    """
    if not xml_content or not xml_content.strip():
        return {}

    stripped = xml_content.lstrip()
    if stripped.startswith("<!DOCTYPE") or "<!DOCTYPE" in stripped[:200]:
        return {}

    parser = etree.XMLParser(
        resolve_entities=False,
        no_network=True,
        load_dtd=False,
        dtd_validation=False,
        remove_blank_text=True,
    )

    try:
        root = etree.fromstring(xml_content.encode("utf-8"), parser=parser)
    except etree.XMLSyntaxError:
        return {}

    if root.tag != "retention-policy":
        return {}

    result: Dict[str, int] = {}
    for rule in root.findall("rule"):
        doc_type = rule.get("document-type")
        if not doc_type:
            continue

        retention_elem = rule.find("retention-years")
        if retention_elem is None or not retention_elem.text:
            continue

        try:
            years = int(retention_elem.text.strip())
        except ValueError:
            continue

        if years <= 0:
            continue

        result[doc_type] = years

    return result
