def build_log_routing_header(tenant_id: str, log_stream: str, tags: dict[str, str] | None = None) -> str:
    """
    Build a log routing header value for the log ingestion pipeline.

    The header routes log batches to the correct partition in a multi-tenant
    log analytics platform. It is sent as 'X-Log-Routing' in HTTP requests
    to the ingestion endpoint.

    Args:
        tenant_id: The tenant identifier (user-supplied, from auth context).
        log_stream: The log stream name (user-supplied, from client config).
        tags: Optional key-value pairs for additional routing dimensions
              (user-supplied, from client metadata).

    Returns:
        A formatted header value string, or empty string if inputs are invalid.
        Format: "tenant=<tenant_id>;stream=<log_stream>;tag1=val1,tag2=val2..."

    Invalid inputs (empty tenant_id, empty log_stream, or any tag key/value
    containing ';' or '=' or ',' or CR/LF) result in an empty string return.
    """
    if not tenant_id or not log_stream:
        return ""

    forbidden_chars = {';', '=', ',', '\r', '\n'}

    def has_forbidden(s: str) -> bool:
        return any(c in s for c in forbidden_chars)

    if has_forbidden(tenant_id) or has_forbidden(log_stream):
        return ""

    if tags is not None:
        for k, v in tags.items():
            if has_forbidden(k) or has_forbidden(v):
                return ""

    parts = [f"tenant={tenant_id}", f"stream={log_stream}"]
    if tags:
        tag_pairs = [f"{k}={v}" for k, v in tags.items()]
        parts.append(",".join(tag_pairs))

    return ";".join(parts)
