import tarfile
import gzip
import io
from typing import Dict


def process_template_bundle(bundle_data: bytes, max_templates: int = 10) -> Dict[str, str]:
    """
    Process a gzipped tarball containing newsletter templates.

    The bundle is expected to contain HTML files (templates) and optionally
    CSS/JS assets. Returns a dictionary mapping template names (filenames without
    extension) to their HTML content.

    Args:
        bundle_data: Raw bytes of the gzipped tarball, provided by the user
                     via template upload endpoint.
        max_templates: Maximum number of template files to extract (default 10).

    Returns:
        Dictionary mapping template names to HTML content strings. Returns
        empty dict if bundle is invalid, empty, or contains no HTML files.
    """
    if not bundle_data:
        return {}

    MAX_DECOMPRESSED_SIZE = 10 * 1024 * 1024  # 10 MB
    MAX_FILE_SIZE = 1 * 1024 * 1024  # 1 MB per file
    MAX_TOTAL_EXTRACTED = 20 * 1024 * 1024  # 20 MB total

    try:
        # Decompress with size limit to prevent gzip bombs
        decompressed = io.BytesIO()
        with gzip.GzipFile(fileobj=io.BytesIO(bundle_data), mode='rb') as gz:
            total_read = 0
            while True:
                chunk = gz.read(8192)
                if not chunk:
                    break
                total_read += len(chunk)
                if total_read > MAX_DECOMPRESSED_SIZE:
                    return {}
                decompressed.write(chunk)
        decompressed_bytes = decompressed.getvalue()
    except (gzip.BadGzipFile, OSError, EOFError):
        return {}

    # Validate tar structure before extraction
    try:
        tar_stream = io.BytesIO(decompressed_bytes)
        with tarfile.open(fileobj=tar_stream, mode='r') as tar:
            members = tar.getmembers()
    except (tarfile.TarError, OSError):
        return {}

    if not members:
        return {}

    # Filter and validate members
    html_members = []
    total_size = 0
    for member in members:
        if not member.isfile():
            continue
        name = member.name
        # Prevent path traversal and absolute paths
        if name.startswith('/') or '..' in name.split('/'):
            continue
        # Only accept .html/.htm files as templates
        if not (name.lower().endswith('.html') or name.lower().endswith('.htm')):
            continue
        if member.size > MAX_FILE_SIZE:
            continue
        total_size += member.size
        if total_size > MAX_TOTAL_EXTRACTED:
            break
        html_members.append(member)
        if len(html_members) >= max_templates:
            break

    if not html_members:
        return {}

    # Extract validated members
    result = {}
    tar_stream = io.BytesIO(decompressed_bytes)
    try:
        with tarfile.open(fileobj=tar_stream, mode='r') as tar:
            for member in html_members:
                try:
                    f = tar.extractfile(member)
                    if f is None:
                        continue
                    content = f.read(MAX_FILE_SIZE + 1)
                    if len(content) > MAX_FILE_SIZE:
                        continue
                    # Decode as UTF-8, replace errors
                    html_content = content.decode('utf-8', errors='replace')
                    template_name = member.name.rsplit('.', 1)[0]
                    # Use basename only for key
                    template_name = template_name.split('/')[-1]
                    if template_name:
                        result[template_name] = html_content
                except (OSError, UnicodeError):
                    continue
    except (tarfile.TarError, OSError):
        return {}

    return result
