from lxml import etree
from typing import Dict, Any, Optional, List, Tuple
import re
import json


def _version_tuple(version: str) -> Tuple[int, ...]:
    """Convert a dot-separated version string to a tuple of ints for comparison."""
    return tuple(int(part) for part in version.split('.'))


def resolve_home_screen_layout(
    layout_config_xml: str,
    user_id: str,
    device_type: str,
    app_version: str,
    locale: str,
    experiment_bucket: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Resolve the personalized home screen layout configuration for a mobile app user
    by querying an XML configuration document with user and device context.

    The XML configuration defines layout variants targeted by device type, minimum
    app version, locale, and optional experiment bucket. Each layout contains an
    ordered list of content blocks with type and position.

    Args:
        layout_config_xml: XML string containing layout definitions. Expected structure:
            <layouts>
              <layout device="ios|android|tablet" min_version="x.y.z" locale="code|*"
                      experiment="bucket_name|*">
                <blocks>
                  <block type="block_type" position="N" config="json_string" />
                  ...
                </blocks>
              </layout>
              ...
            </layouts>
        user_id: Unique user identifier (from authenticated session).
        device_type: Client device type: "ios", "android", or "tablet" (from client).
        app_version: Client app version string, e.g., "3.2.1" (from client).
        locale: User locale code, e.g., "en_US", "fr_FR" (from client).
        experiment_bucket: Optional A/B experiment bucket assignment (from server-side
            experiment service). If provided, matches layouts with same experiment
            attribute or wildcard "*".

    Returns:
        Dictionary with layout configuration:
        {
            "layout_id": str,           # matched layout's device+locale+experiment key
            "blocks": [                 # ordered by position ascending
                {"type": str, "position": int, "config": dict},
                ...
            ]
        }
        Returns empty dict {} if no matching layout is found or XML is malformed.

    User-controlled inputs:
        user_id, device_type, app_version, locale, experiment_bucket all originate
        from client requests or downstream services and must be treated as untrusted.
    """
    # Validate and sanitize inputs before use
    allowed_device_types = {"ios", "android", "tablet"}
    if device_type not in allowed_device_types:
        return {}

    # Validate app_version format (semver-like: digits and dots only)
    if not re.match(r'^\d+(\.\d+)*$', app_version):
        return {}

    # Validate locale format (language[_REGION] with alphanumeric and underscore)
    if not re.match(r'^[a-z]{2}(_[A-Z]{2})?$', locale):
        return {}

    # Validate experiment_bucket if provided (alphanumeric, dash, underscore)
    if experiment_bucket is not None:
        if not re.match(r'^[a-zA-Z0-9_-]+$', experiment_bucket):
            return {}

    # user_id is used only for logging/auditing in real implementation;
    # here we just validate it's a non-empty string
    if not user_id or not isinstance(user_id, str):
        return {}

    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True)
        root = etree.fromstring(layout_config_xml.encode('utf-8'), parser=parser)
    except (etree.XMLSyntaxError, UnicodeError):
        return {}

    # Build XPath with parameterized variables - NO string interpolation
    # Version comparison is done in Python after selection to avoid XPath 1.0
    # number conversion issues with dotted version strings.
    exp_value = experiment_bucket if experiment_bucket is not None else "*"
    xpath_expr = (
        "//layout["
        "@device = $device_type and "
        "(@locale = $locale or @locale = '*') and "
        "(@experiment = $experiment_bucket or @experiment = '*')"
        "]"
    )

    xpath_vars = {
        "device_type": device_type,
        "locale": locale,
        "experiment_bucket": exp_value,
    }

    try:
        matched_layouts = root.xpath(xpath_expr, **xpath_vars)
    except etree.XPathError:
        return {}

    if not matched_layouts:
        return {}

    # Filter by minimum version (app_version >= min_version)
    app_ver_tuple = _version_tuple(app_version)
    version_filtered = []
    for layout in matched_layouts:
        min_ver_str = layout.get("min_version", "0.0.0")
        try:
            min_ver_tuple = _version_tuple(min_ver_str)
        except ValueError:
            continue
        if app_ver_tuple >= min_ver_tuple:
            version_filtered.append(layout)

    if not version_filtered:
        return {}

    # Select the most specific match (prefer non-wildcard locale/experiment)
    def specificity(layout):
        loc_spec = 0 if layout.get("locale") == "*" else 1
        exp_spec = 0 if layout.get("experiment") == "*" else 1
        return (loc_spec, exp_spec)

    version_filtered.sort(key=specificity, reverse=True)
    layout = version_filtered[0]

    # Extract blocks
    blocks = []
    for block_elem in layout.xpath(".//block"):
        try:
            block_type = block_elem.get("type", "")
            position_str = block_elem.get("position", "0")
            position = int(position_str)
            config_str = block_elem.get("config", "{}")
            config = json.loads(config_str) if config_str else {}
            if block_type:
                blocks.append({
                    "type": block_type,
                    "position": position,
                    "config": config
                })
        except (ValueError, json.JSONDecodeError):
            continue

    # Sort blocks by position
    blocks.sort(key=lambda b: b["position"])

    # Construct layout_id from matched attributes
    layout_id = f"{layout.get('device','')}_{layout.get('locale','')}_{layout.get('experiment','')}"

    return {
        "layout_id": layout_id,
        "blocks": blocks
    }
