from typing import Optional


def process_supplemental_docs(
    claim_id: str,
    user_updates: dict,
    current_claim: dict
) -> Optional[dict]:
    """
    Process supplemental documentation updates for an insurance claim.

    Updates allowed fields on a claim record based on user-provided documentation.
    Only specific fields related to documentation and metadata should be updatable.

    Args:
        claim_id: The unique identifier for the claim (from URL path, trusted).
        user_updates: Dictionary of field updates from the claimant's portal
            submission (USER INPUT).
        current_claim: Current claim record from the database (trusted).

    Returns:
        Updated claim dictionary with only allowed fields modified, or None if
        claim_id does not match current_claim['claim_id'].

    Allowed updatable fields from user_updates:
        - supplemental_docs: list of document references (strings)
        - damage_description: updated description text (string)
        - repair_estimates: list of estimate amounts (numbers)
        - contact_preference: one of 'email', 'phone', 'mail' (string)
        - metadata: dict of arbitrary claimant-provided notes (string keys, any values)

    Fields that must NOT be updatable from user_updates (ignored if present):
        - approved_amount, status, adjuster_id, fraud_flag, policy_limit,
          deductible_applied, depreciation_schedule, created_at, claim_number,
          claim_id, version
    """
    if not isinstance(current_claim, dict):
        return None
    if current_claim.get("claim_id") != claim_id:
        return None

    allowed_fields = {
        "supplemental_docs",
        "damage_description",
        "repair_estimates",
        "contact_preference",
        "metadata",
    }

    valid_contact_prefs = {"email", "phone", "mail"}

    updated_claim = current_claim.copy()
    updated_claim["version"] = current_claim.get("version", 0) + 1

    for field in allowed_fields:
        if field in user_updates:
            value = user_updates[field]
            if field == "contact_preference":
                if isinstance(value, str) and value in valid_contact_prefs:
                    updated_claim[field] = value
            elif field == "supplemental_docs":
                if isinstance(value, list) and all(isinstance(d, str) for d in value):
                    updated_claim[field] = value
            elif field == "damage_description":
                if isinstance(value, str):
                    updated_claim[field] = value
            elif field == "repair_estimates":
                if isinstance(value, list) and all(
                    isinstance(e, (int, float)) for e in value
                ):
                    updated_claim[field] = value
            elif field == "metadata":
                if isinstance(value, dict) and all(isinstance(k, str) for k in value):
                    updated_claim[field] = value

    return updated_claim
